    crate::storybook::gallery::DocPage::new("OtpField").description("The one-time code a reader is copying out of a message. It is a run of cells rather than a single field because that is what makes it fast: Base UI moves the caret between them, takes a paste of the whole code into all of them at once, hands the browser the autofill hint that pulls the code out of an SMS, and can submit the form the moment the last cell fills.").child(crate::storybook::gallery::Section::new("Sizes").description("Each cell is the text controls' box at one character wide, so a code sits on the same rhythm as the fields around it — a code entered in a box of its own design would be the only control on the page that was. The mono face and tabular figures keep the digits on one width.").child(crate::storybook::gallery::Specimens::new().child(crate::storybook::gallery::Specimen::new("small").child(dazzui::OtpField::new("components-otpfield--overview-0-0-0-0", &state.generated.fields["components-otpfield--overview-0-0-0-0"], 6).mask(false).size(dazzui::TextFieldSize::Small).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(false).into_any_element()).into_any_element()).child(crate::storybook::gallery::Specimen::new("medium").child(dazzui::OtpField::new("components-otpfield--overview-0-0-1-0", &state.generated.fields["components-otpfield--overview-0-0-1-0"], 6).mask(false).size(dazzui::TextFieldSize::Medium).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(false).into_any_element()).into_any_element()).child(crate::storybook::gallery::Specimen::new("large").child(dazzui::OtpField::new("components-otpfield--overview-0-0-2-0", &state.generated.fields["components-otpfield--overview-0-0-2-0"], 6).mask(false).size(dazzui::TextFieldSize::Large).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(false).into_any_element()).into_any_element()).into_any_element()).into_any_element()).child(crate::storybook::gallery::Section::new("Grouping").description("`groupAfter` breaks the run where a printed code breaks — three and three is how a six-digit code is read aloud. It is a step of air rather than a rule, because a rule would read as two fields.").child(crate::storybook::gallery::Specimens::new().child(crate::storybook::gallery::Specimen::new("ungrouped").child(dazzui::OtpField::new("components-otpfield--overview-1-0-0-0", &state.generated.fields["components-otpfield--overview-1-0-0-0"], 6).mask(false).size(dazzui::TextFieldSize::Medium).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(false).into_any_element()).into_any_element()).child(crate::storybook::gallery::Specimen::new("groupAfter 3").child(dazzui::OtpField::new("components-otpfield--overview-1-0-1-0", &state.generated.fields["components-otpfield--overview-1-0-1-0"], 6).group_after(3).mask(false).size(dazzui::TextFieldSize::Medium).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(false).into_any_element()).into_any_element()).into_any_element()).into_any_element()).child(crate::storybook::gallery::Section::new("Masked and disabled").description("`mask` is for a code that is a secret rather than a one-time token — a PIN. A filled cell lifts to the paper and keeps it, so the run says how far through the code the reader is without the caret having to be the only thing that does.").child(crate::storybook::gallery::Specimens::new().child(crate::storybook::gallery::Specimen::new("masked").child(dazzui::OtpField::new("components-otpfield--overview-2-0-0-0", &state.generated.fields["components-otpfield--overview-2-0-0-0"], 4).mask(true).size(dazzui::TextFieldSize::Medium).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(false).into_any_element()).into_any_element()).child(crate::storybook::gallery::Specimen::new("disabled").child(dazzui::OtpField::new("components-otpfield--overview-2-0-1-0", &state.generated.fields["components-otpfield--overview-2-0-1-0"], 6).mask(false).size(dazzui::TextFieldSize::Medium).state(dazzui::TextFieldState::Default).tint(Tint::Primary).disabled(true).into_any_element()).into_any_element()).into_any_element()).into_any_element()).into_any_element()
