    fn components_textfield_controlled_1(cx: &mut gpui::TestAppContext) {
        let (view, cx) = cx.add_window_view(|_, cx| crate::Playground::new(cx));
        view.update(cx, |state, cx| {
            state.selection = crate::storybook::StoryRef::new("TextField", "Controlled");
            cx.notify();
        });
        cx.run_until_parked();
        let target = cx
            .debug_bounds("name")
            .expect("shared checkpoint target is visible")
            .center();
        cx.simulate_click(target, gpui::Modifiers::default());
        cx.run_until_parked();
        cx.simulate_keystrokes("cmd-a backspace");
        cx.simulate_input("");
        cx.run_until_parked();
        view.update(cx, |state, _| {
            assert_eq!(state.generated.disabled_values.borrow()["export"], true);
            assert_eq!(state.generated.values["name"], Value::Text("".into()));
        });
    }

